const $ = s => document.querySelector(s);
const defaults = {target:23, mode:'auto', manual:65, unit:'C', paused:false};
let saved={};try{saved=JSON.parse(localStorage.getItem('ember-settings')||'{}')}catch{}
let s={...defaults,...saved,current:21.4,live:false,duty:65,hashrate:4820,heating:true,error:null};
s.target=Number.isFinite(s.target)?Math.max(16,Math.min(30,s.target)):23;s.manual=Number.isFinite(s.manual)?Math.max(10,Math.min(100,s.manual)):65;s.mode=['auto','manual','off'].includes(s.mode)?s.mode:'auto';s.unit=s.unit==='F'?'F':'C';
let events=[],samples=[],period=1,commandVersion=0,pending=false;
const temperature=(c,d=0)=>(s.unit==='F'?c*9/5+32:c).toFixed(d);
function persist(){try{localStorage.setItem('ember-settings',JSON.stringify(Object.fromEntries(Object.keys(defaults).map(k=>[k,s[k]]))))}catch{}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function log(t){events.unshift({time:new Date().toISOString(),event:t});events=events.slice(0,200);$('#activity-log').replaceChildren(...events.map(e=>{const row=document.createElement('div');row.className='log-row';const text=document.createElement('span');text.textContent=e.event;const time=document.createElement('time');time.textContent=new Date(e.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});row.append(text,time);return row}))}
function updateDemo(){if(s.live)return;s.duty=s.mode==='off'||s.paused?0:s.mode==='manual'?s.manual:Math.round(Math.min(100,Math.max(0,(s.target-s.current)*40)));if(s.mode==='auto'&&s.current>=s.target+.3)s.duty=0;s.heating=s.duty>0;s.hashrate=7420*s.duty/100;}
function render(){updateDemo();const heat=s.heating&&!s.paused&&s.mode!=='off'&&!s.error;$('#target').textContent=temperature(s.target);$('#current').textContent=temperature(s.current,1);document.querySelectorAll('.unit-label').forEach(e=>e.textContent=s.unit);$('.dial-min').textContent=temperature(16)+'°';$('.dial-max').textContent=temperature(30)+'°';const frac=(s.target-16)/14;$('#dial-progress').style.strokeDasharray=`${frac*100} 100`;const a=(135+270*frac)*Math.PI/180;$('#dial-knob').setAttribute('cx',200+164*Math.cos(a));$('#dial-knob').setAttribute('cy',200+164*Math.sin(a));$('#state-pill').innerHTML=`<i></i>${s.error?'Sensor fault':s.mode==='off'?'Off':s.paused?'Paused':heat?'Heating':'At ease'}`;$('#heat-caption').textContent=s.error?'Mining stopped · check connection':heat?`Warming up to ${temperature(s.target)}°${s.unit}`:s.paused?'Mining is paused':s.mode==='off'?'Thermostat is off':'Comfort temperature reached';$('#hashrate').textContent=(s.hashrate/1000).toFixed(2);$('#watts').textContent=s.live?'—':Math.round(285*s.duty/100);$('.heat-note').innerHTML=s.live?'Power meter not connected':'<span>≈</span> Every watt becomes warmth';$('#intensity-value').textContent=s.duty;$('#intensity').value=s.mode==='manual'?s.manual:s.duty;$('#intensity').disabled=s.mode!=='manual'||s.paused;$('#intensity').style.background=`linear-gradient(to right,#aebd98 ${s.duty}%,#eceee5 ${s.duty}%)`;$('#auto-tag').textContent=s.mode==='auto'?'· Auto adjusted':s.mode==='manual'?'· Manual limit':'· Powered down';$('#miner-status').textContent=s.error?'Connection fault':(s.live?'XMRig':'Demo miner')+(heat?' running':' paused');$('#pause').innerHTML=s.paused?'▶ <span>Resume mining</span>':'Ⅱ <span>Pause mining</span>';$('#mining-title').textContent=s.error?'Taking a safe pause.':heat?'Good work. Good warmth.':'A comfortable little break.';$('#mining-subtitle').textContent=s.error?s.error:heat?'Your miner is making itself useful.':'Ready when your room needs a little warmth.';$('.connection span').textContent=s.live?'Local bridge connected':'Demo environment';$('#sensor-label').textContent=s.live?'Live room sensor':'Simulated sensor';$('#footer-mode').innerHTML=s.live?'<i></i>Local control <span>·</span> Live sensor':'<i></i>Demo mode <span>·</span> No real mining';$('#history-caption').textContent=s.live?'Live readings · Recorded since connection':'Demo data · Preview of a typical warming cycle';$('#history-chart').setAttribute('aria-label',s.live?'Recorded room temperature history':'Simulated room temperature history');document.querySelectorAll('.mode').forEach(e=>e.classList.toggle('active',e.dataset.mode===s.mode));$('#mode-description').textContent={auto:'Just the right amount of mining to keep you comfortable.',manual:'Set the proportion of time your miner spends producing heat.',off:'Take a break. Your miner will stay paused.'}[s.mode];$('#celsius').classList.toggle('selected',s.unit==='C');$('#fahrenheit').classList.toggle('selected',s.unit==='F');$('#minus').disabled=s.target<=16;$('#plus').disabled=s.target>=30;drawChart();}
function drawChart(){let values;if(s.live){const recent=samples.filter(p=>Date.now()-p.time<=period*3600000);values=recent.map(p=>p.temp);if(!values.length)values=[s.current];}else{values=Array.from({length:65},(_,i)=>18.5+2.9*(1-Math.exp(-i/(period===1?22:15)))+.10*Math.sin(i*.7)+.04*Math.cos(i*2.1));}const y=c=>146-(c-17)/9*138;const pts=values.map((v,i)=>`${values.length===1?1000:i/(values.length-1)*1000},${y(v)}`);const path='M'+pts.join(' L');$('#chart-line').setAttribute('d',path);$('#chart-area').setAttribute('d',path+' L1000,155 L0,155 Z');$('#chart-dot').setAttribute('cy',y(values.at(-1)));$('#target-line').setAttribute('d',`M0 ${y(s.target)}H1000`);document.querySelectorAll('.y-labels span').forEach((e,i)=>e.textContent=temperature([26,23,20,17][i])+'°');$('#x-labels').replaceChildren(...Array.from({length:7},(_,i)=>{const e=document.createElement('span');e.textContent=i===6?'Now':new Date(Date.now()-(6-i)*period*600000).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});return e}));}
async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(7000)});if(!r.ok){let msg='Local bridge unavailable';try{msg=(await r.json()).error||msg}catch{}throw Error(msg)}return r.json()}
function adopt(data){s={...s,...data,live:true};samples.push({time:Date.now(),temp:s.current});samples=samples.slice(-18000);render()}
async function send(){persist();render();if(!s.live)return;const version=++commandVersion;pending=true;try{const data=await api('/api/control',{target:s.target,mode:s.mode,manual:s.manual,paused:s.paused});if(version===commandVersion)adopt(data)}catch(e){s.error=e.message;s.heating=false;s.hashrate=0;render();toast(e.message)}finally{if(version===commandVersion)pending=false}}
async function checkConnection(user=false){try{const data=await api('/api/status');if(data.kind!=='ember-bridge')throw Error('Not a local bridge');adopt(data);if(user){$('#connection-result').textContent='Local bridge connected. Live thermostat control is ready.';toast('Live room connected')}}catch{if(user)$('#connection-result').textContent='This is the hosted demo. Start bridge.py and open http://127.0.0.1:8787 on your mining computer.'}}
$('#minus').onclick=()=>{s.target=Math.max(16,s.target-1);log(`Target set to ${temperature(s.target)}°${s.unit}`);send()};$('#plus').onclick=()=>{s.target=Math.min(30,s.target+1);log(`Target set to ${temperature(s.target)}°${s.unit}`);send()};document.querySelectorAll('.mode').forEach(e=>e.onclick=()=>{s.mode=e.dataset.mode;log(`Thermostat switched to ${s.mode}`);send()});$('#pause').onclick=()=>{s.paused=!s.paused;log(s.paused?'Mining paused':'Mining resumed');send()};$('#intensity').oninput=e=>{s.manual=Number(e.target.value);render()};$('#intensity').onchange=()=>{log(`Manual duty cycle set to ${s.manual}%`);send()};document.querySelectorAll('.nav').forEach(e=>e.onclick=()=>{document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n===e));document.querySelectorAll('.view').forEach(v=>v.classList.toggle('hidden',v.id!==e.dataset.view+'-view'))});document.querySelectorAll('[data-period]').forEach(e=>e.onclick=()=>{period=Number(e.dataset.period);document.querySelectorAll('[data-period]').forEach(n=>n.classList.toggle('selected',n===e));drawChart()});['C','F'].forEach(unit=>$(unit==='C'?'#celsius':'#fahrenheit').onclick=()=>{s.unit=unit;persist();render();toast(`Temperature shown in °${unit}`)});$('#connection').onclick=$('#connect-settings').onclick=()=>$('#connection-dialog').showModal();$('.close-dialog').onclick=()=>$('#connection-dialog').close();$('#check-bridge').onclick=()=>checkConnection(true);$('#export').onclick=()=>{const csv='time,event\n'+events.map(e=>`"${e.time}","${e.event.replaceAll('"','""')}"`).join('\n');const a=document.createElement('a');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.href=url;a.download='ember-session.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Session exported')};
const svgNS='http://www.w3.org/2000/svg';for(let i=0;i<=72;i++){const a=(135+i*270/72)*Math.PI/180;const line=document.createElementNS(svgNS,'line');const r=i%6===0?184:188;line.setAttribute('x1',200+r*Math.cos(a));line.setAttribute('y1',200+r*Math.sin(a));line.setAttribute('x2',200+193*Math.cos(a));line.setAttribute('y2',200+193*Math.sin(a));$('#ticks').append(line)}for(let i=0;i<25;i++){const b=document.createElement('i');b.style.height=(8+(i%7)*1.6+Math.sin(i*1.6)*4)+'px';$('#hash-bars').append(b)}$('#clock').textContent=new Date().toLocaleDateString([],{weekday:'long',month:'long',day:'numeric'});log('Demo environment opened');render();checkConnection();setInterval(async()=>{if(s.live){if(pending)return;try{adopt(await api('/api/status'))}catch{ s.error='Bridge connection lost';s.heating=false;s.hashrate=0;render()}}else{const ambient=18;s.current+=((s.duty/100)*.011-(s.current-ambient)*.0012);render()}},5000);
